from collections import Counter
def analyze(I):
    cnt=Counter(x for row in I for x in row)
    bg=cnt.most_common(1)[0][0]; sep=cnt.most_common(2)[1][0]
    H,W=len(I),len(I[0])
    srows=[r for r in range(H) if sum(1 for x in I[r] if x==sep)>W/2]
    scols=[c for c in range(W) if sum(1 for r in range(H) if I[r][c]==sep)>H/2]
    markers=[(r,c,I[r][c]) for r in range(H) for c in range(W) if I[r][c] not in (bg,sep)]
    return bg,sep,srows,scols,markers

def lattice_bands(lines):
    return list(zip(lines,lines[1:]))

def transform(I):
    bg,sep,srows,scols,markers=analyze(I)
    mrows=sorted({r for r,c,v in markers}); mcols=sorted({c for r,c,v in markers})
    corner_style = all(r in srows for r in mrows) and all(c in scols for c in mcols)
    # build output row bands: for consecutive marked rows, expand by lattice gaps
    def expand(mlines, lattice):
        bands=[]
        for a,b in zip(mlines,mlines[1:]):
            if a in lattice and b in lattice:
                ia,ib=lattice.index(a),lattice.index(b)
                for k in range(ia,ib): bands.append((lattice[k],lattice[k+1]))
            else:
                bands.append((a,b))
        return bands
    rbands=expand(mrows,srows); cbands=expand(mcols,scols)
    M={(r,c):v for r,c,v in markers}
    out=[]
    for ra,rb in rbands:
        row=[]
        for ca,cb in cbands:
            corners=[M.get((ra,ca)),M.get((ra,cb)),M.get((rb,ca)),M.get((rb,cb))]
            if None in corners: row.append(bg)
            elif len(set(corners))==1: row.append(corners[0])
            elif corner_style: row.append(bg)
            else: row.append(sep)
        out.append(row)
    return out

for name,(i,o) in {'d1':(I1,O1),'d3':(I3,O3),'d2':(I2,O2)}.items():
    p=transform(i)
    print(name,'match' if p==o else 'MISMATCH', p, 'expected', o)
